   276	func (r *routes) waitForAction(ctx context.Context, action *hcloud.Action) error {
   277		if action == nil {
   278			return nil
   279		}
   280	
   281		for {
   282			switch action.Status {
   283			case hcloud.ActionStatusSuccess:
   284				return nil
   285			case hcloud.ActionStatusError:
   286				if err := action.Error(); err != nil {
   287					return err
   288				}
   289				return fmt.Errorf("action %d failed", action.ID)
   290			case hcloud.ActionStatusRunning:
   291			default:
   292				return nil
   293			}
   294	
   295			next, _, err := r.client.Action.GetByID(ctx, action.ID)
   296			if err != nil {
   297				return err
   298			}
   299			if next == nil {
   300				return fmt.Errorf("action %d not found", action.ID)
   301			}
   302			action = next
   303	
   304			if action.Status != hcloud.ActionStatusRunning {
   305				continue
   306			}
   307	
   308			select {
   309			case <-ctx.Done():
   310				return ctx.Err()
